CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id), company_id uuid REFERENCES companies(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE categories (code text PRIMARY KEY, label text NOT NULL, requires_enhanced_screening boolean NOT NULL DEFAULT false);
INSERT INTO categories(code,label,requires_enhanced_screening) VALUES ('cleaning','General Cleaning',false),('babysitting','Nanny / Babysitting',true),('hair','Hair Services',false),('plumbing','Plumbing',false),('tutorial','Tutorial Services',true);
CREATE TABLE provider_categories (provider_id uuid NOT NULL REFERENCES providers(id), category_code text NOT NULL REFERENCES categories(code), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','suspended')), approved_at timestamptz, expires_at timestamptz, PRIMARY KEY(provider_id,category_code));
CREATE TABLE availability (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES providers(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, CHECK (ends_at>starts_at));
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), category_code text NOT NULL REFERENCES categories(code), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, address_text text NOT NULL, intake jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','matching','confirmed','in_progress','completed','settled','canceled','disputed')), agreed_price_cents bigint, currency char(3) NOT NULL DEFAULT 'PHP', created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE dispatch_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), provider_id uuid NOT NULL REFERENCES providers(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','expired')), expires_at timestamptz NOT NULL, UNIQUE(booking_id,provider_id));
CREATE TABLE assignments (booking_id uuid PRIMARY KEY REFERENCES bookings(id), provider_id uuid NOT NULL REFERENCES providers(id), assigned_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE booking_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, booking_id uuid NOT NULL REFERENCES bookings(id), actor_user_id uuid REFERENCES users(id), event_type text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), provider_id uuid NOT NULL REFERENCES providers(id), amount_cents bigint NOT NULL CHECK(amount_cents>=0), status text NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_approved_quote_per_booking ON quotes(booking_id) WHERE status='approved';
CREATE TABLE payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), amount_cents bigint NOT NULL CHECK(amount_cents>=0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','failed','refunded')), external_reference text UNIQUE);
CREATE INDEX idx_booking_customer ON bookings(customer_id,created_at DESC);
CREATE INDEX idx_offer_provider ON dispatch_offers(provider_id,status);
